def test_different_number_of_cols(self):
    expected = self.read_html('<table>\n                        <thead>\n                            <tr style="text-align: right;">\n                            <th></th>\n                            <th>C_l0_g0</th>\n                            <th>C_l0_g1</th>\n                            <th>C_l0_g2</th>\n                            <th>C_l0_g3</th>\n                            <th>C_l0_g4</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr>\n                            <th>R_l0_g0</th>\n                            <td> 0.763</td>\n                            <td> 0.233</td>\n                            <td> nan</td>\n                            <td> nan</td>\n                            <td> nan</td>\n                            </tr>\n                            <tr>\n                            <th>R_l0_g1</th>\n                            <td> 0.244</td>\n                            <td> 0.285</td>\n                            <td> 0.392</td>\n                            <td> 0.137</td>\n                            <td> 0.222</td>\n                            </tr>\n                        </tbody>\n                    </table>', index_col=0)[0]
    result = self.read_html('<table>\n                    <thead>\n                        <tr style="text-align: right;">\n                        <th></th>\n                        <th>C_l0_g0</th>\n                        <th>C_l0_g1</th>\n                        <th>C_l0_g2</th>\n                        <th>C_l0_g3</th>\n                        <th>C_l0_g4</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr>\n                        <th>R_l0_g0</th>\n                        <td> 0.763</td>\n                        <td> 0.233</td>\n                        </tr>\n                        <tr>\n                        <th>R_l0_g1</th>\n                        <td> 0.244</td>\n                        <td> 0.285</td>\n                        <td> 0.392</td>\n                        <td> 0.137</td>\n                        <td> 0.222</td>\n                        </tr>\n                    </tbody>\n                 </table>', index_col=0)[0]
    tm.assert_frame_equal(result, expected)